-- This is an editorial debate by fictional personas. No member records or engagement are seeded.
values ('iowa-army-detonation', 'Should the Army have detonated the unstable lead azide stockpile in Iowa?', 'Public safety & environment')
on conflict (slug) do nothing;

on conflict (slug,id) do nothing;

on conflict (id) do nothing;

-- Expose only the count of simulated likes given on currently visible sample posters.
create function public.dk_sample_support_given(p_persona text) returns bigint
language sql stable security definer set search_path='' as $$
  select count(*)
  from dk_editorial.poster_activity a
  join public.dk_infographics p on p.slug=a.slug and p.owner_id is null
  where a.persona=p_persona and a.liked and p.published_at<=now();
$$;
revoke all on function public.dk_sample_support_given(text) from public;
grant execute on function public.dk_sample_support_given(text) to anon,authenticated;
