insert into public.dk_infographics(slug,title,category)
insert into dk_safety.points(slug,id,side,rank,title,detail,sources,counterpoint) values
  ('iowa-army-detonation', 'ccd224e2-6e19-5671-aa29-c261f06b53bd', 'Proceed with safeguards', 1, 'Reduce the no-warning risk', 'The Army reported that inspection found a severely degraded stockpile and concluded that an uncontrolled explosion could occur. A planned event gave responders a chance to protect people in advance. That was the strongest case for acting on November 25.', '["https://www.army.mil/article/297069/army_announces_controlled_detonation_of_degraded_explosive_material_at_iowa_army_ammunition_plant", "https://www.kcrg.com/2026/11/22/lead-explosion-experts-question-emergency-army-vows-blast-will-proceed/"]'::jsonb, 'The inspection finding establishes a hazard. The public record offers less clarity about how likely a failure was during one additional day of review.'),
  ('iowa-army-detonation', '226622f9-1791-58cd-80bd-9cdf7a820f71', 'Proceed with safeguards', 5, 'Avoid moving the stockpile', 'The Army’s technical review considered off-site transport and other options unsafe under the conditions it identified. Moving the hazard would also have exposed workers and places beyond the installation to a risk they did not face while it stayed on site.', '["https://www.army.mil/article/297069/army_announces_controlled_detonation_of_degraded_explosive_material_at_iowa_army_ammunition_plant", "https://earthjustice.org/press/2026/army-detonates-nearly-five-tons-of-lead-azide-in-iowa-town"]'::jsonb, 'Ask an independent reviewer to check whether alternatives had been ruled out across the entire stockpile and whether they could have been used earlier.'),
  ('iowa-army-detonation', 'e20f4108-4c85-5ed0-bbb0-638453e5fd9a', 'Proceed with safeguards', 9, 'Use the better weather window', 'The operation was delayed until November 25. The government told the court the revised date offered more favorable weather and time for additional protections. A planned event could use that window. An accidental blast would not.', '["https://earthjustice.org/wp-content/uploads/2026/11/2026-11-23-doj-notice-of-operation.pdf", "https://apnews.com/article/iowa-lead-detonation-714e040baedc1cd90c2ba688be76cfc7", "https://epa.illinois.gov/about-us/illinois-epa-news/illinois-remains-on-standby-following-lead-azide-detonation-at-t.html"]'::jsonb, 'Forecasts can help choose a day but cannot settle what reached the ground. Keep sampling after the decision.'),
  ('iowa-army-detonation', 'fb83a53c-62ab-5540-91f4-4e63412351d9', 'Proceed with safeguards', 16, 'Prepare people before the event', 'A planned operation made it possible to issue alerts, arrange lodging or transport, and advise people in the nearest areas before the blast. Even imperfect advance warning is valuable when the alternative may arrive without warning.', '["https://www.army.mil/article/297039/public_safety_advisory_controlled_mitigated_detonation_of_unstable_lead_azide_at_iowa_army_ammunition_plant", "https://apnews.com/article/iowa-lead-detonation-714e040baedc1cd90c2ba688be76cfc7", "https://earthjustice.org/press/2026/army-detonates-nearly-five-tons-of-lead-azide-in-iowa-town"]'::jsonb, 'Support is useful only if people hear about it in time and can actually use it. Residents reported confusion during the run-up.'),
  ('iowa-army-detonation', '4968ab58-a8a7-5902-bcd9-6d9217e85945', 'Proceed with safeguards', 18, 'Coordinate agencies and responders', 'The military, EPA and local agencies coordinated ahead of the operation. Prepared monitors and responders could be in place as it happened. With a sudden incident, those teams might have to organize while dealing with the incident itself.', '["https://www.army.mil/article/297069/army_announces_controlled_detonation_of_degraded_explosive_material_at_iowa_army_ammunition_plant", "https://www.epa.gov/newsreleases/epa-collects-over-1200-air-land-and-water-samples-ahead-iowa-army-ammunition-plant", "https://epa.illinois.gov/about-us/illinois-epa-news/illinois-remains-on-standby-following-lead-azide-detonation-at-t.html"]'::jsonb, 'Agency coordination helps, but advice and re-entry decisions still need a clear public owner and a timetable.'),
  ('iowa-army-detonation', '15d2abb5-2e2f-5aed-a54b-80cb54b237d1', 'Proceed with safeguards', 11, 'Measure against a baseline', 'EPA collected 1,216 samples across soil, dust, water and air before the operation. Those samples give investigators a comparison for later results. Starting only after an unplanned event would make it harder to tell what changed.', '["https://www.epa.gov/newsreleases/epa-collects-over-1200-air-land-and-water-samples-ahead-iowa-army-ammunition-plant", "https://www.epa.gov/newsreleases/initial-air-monitoring-shows-zero-detection-airborne-lead-following-controlled"]'::jsonb, 'A useful baseline needs comparable locations and methods. Its existence does not establish what later sampling will find.'),
  ('iowa-army-detonation', '786cfeba-4ad0-5448-9e40-e35f9c2ce08e', 'Proceed with safeguards', 10, 'Separate the two risks', 'The choice was between a scheduled disposal with safeguards and allowing a known hazard to remain while other options were considered. Judging the operation against a world with no blast risk would miss why the Army acted.', '["https://www.army.mil/article/297069/army_announces_controlled_detonation_of_degraded_explosive_material_at_iowa_army_ammunition_plant", "https://earthjustice.org/wp-content/uploads/2026/11/2026-11-23-doj-notice-of-operation.pdf", "https://www.kcrg.com/2026/11/22/lead-explosion-experts-question-emergency-army-vows-blast-will-proceed/"]'::jsonb, 'Compare against a specific, time-limited review as well as against an open-ended delay. The risk of those alternatives is different.'),
  ('iowa-army-detonation', '6cd83dbb-0bac-5f94-a983-0160f6429787', 'Proceed with safeguards', 14, 'End the stockpile hazard', 'The Army told AP that both detonations destroyed all 68 barrels and that it saw no secondary explosions. That addresses whether the immediate stockpile hazard was removed. It is one part of evaluating the outcome.', '["https://apnews.com/article/iowa-lead-detonation-714e040baedc1cd90c2ba688be76cfc7"]'::jsonb, 'Destruction of the material is an operational result. It cannot by itself settle what happened off-site.'),
  ('iowa-army-detonation', 'd99e1c48-f402-5f77-a5c3-390710d18877', 'Proceed with safeguards', 20, 'Respect the early evidence', 'EPA reported no airborne lead detected by its real-time monitors in its initial release. That is useful evidence about what those instruments detected around the event, and it belongs in any assessment of whether the precautions helped.', '["https://www.epa.gov/newsreleases/initial-air-monitoring-shows-zero-detection-airborne-lead-following-controlled", "https://apnews.com/article/iowa-lead-detonation-714e040baedc1cd90c2ba688be76cfc7"]'::jsonb, 'Non-detection at those monitors does not establish that nothing settled on soil or surfaces. The lab results can answer different questions.'),
  ('iowa-army-detonation', '8a0ea2db-25f7-5742-96c8-bfb5d033b5cf', 'Proceed with safeguards', 12, 'Keep the follow-up commitment', 'Acting in an emergency and staying accountable afterward are compatible. The Army and EPA could defend the timing while committing to release measured results, remediate any attributable contamination, and investigate how storage became a crisis.', '["https://www.epa.gov/newsreleases/initial-air-monitoring-shows-zero-detection-airborne-lead-following-controlled", "https://epa.illinois.gov/about-us/illinois-epa-news/illinois-remains-on-standby-following-lead-azide-detonation-at-t.html", "https://earthjustice.org/press/2026/army-detonates-nearly-five-tons-of-lead-azide-in-iowa-town"]'::jsonb, 'A commitment needs named responsibilities, dates, and a way for residents to challenge gaps in coverage.'),
  ('iowa-army-detonation', '993b1935-71d5-55e1-84ca-87ce53bfeb2d', 'Require stronger review', 3, 'Show why another day was unsafe', 'Experts cited by local reporting disputed the government’s assessment of imminence. They did not show that storage was safe indefinitely. Their challenge was whether the Army demonstrated that a short, independently reviewed delay would be riskier than proceeding.', '["https://www.kcrg.com/2026/11/22/lead-explosion-experts-question-emergency-army-vows-blast-will-proceed/", "https://www.army.mil/article/297069/army_announces_controlled_detonation_of_degraded_explosive_material_at_iowa_army_ammunition_plant"]'::jsonb, 'The officials accountable for worker and public safety judged the hazard very serious. They may not have been able to guarantee even one extra day.'),
  ('iowa-army-detonation', '44869e5e-7b1c-5f96-bb7c-107f76c59352', 'Require stronger review', 6, 'Examine earlier intervention', 'Earthjustice pointed to the Army’s prior awareness of deterioration and asked why action came so late. Even if the November choice was warranted, an inquiry could ask when different options were still possible and who owned that decision.', '["https://earthjustice.org/press/2026/army-detonates-nearly-five-tons-of-lead-azide-in-iowa-town", "https://www.army.mil/article/297069/army_announces_controlled_detonation_of_degraded_explosive_material_at_iowa_army_ammunition_plant"]'::jsonb, 'Long-term storage failures deserve a review. They do not, on their own, show that postponing the operation on November 25 was safer.'),
  ('iowa-army-detonation', 'd3236afd-d48b-5bbc-b6fe-6f4d9cfe472e', 'Require stronger review', 7, 'Review alternatives in public', 'The Army said it evaluated other options and concluded that none were viable. An independent review could test which options were rejected because of the immediate hazard, which assumptions drove the judgment, and what the team still did not know.', '["https://www.army.mil/article/297069/army_announces_controlled_detonation_of_degraded_explosive_material_at_iowa_army_ammunition_plant", "https://www.kcrg.com/2026/11/22/lead-explosion-experts-question-emergency-army-vows-blast-will-proceed/", "https://earthjustice.org/press/2026/army-detonates-nearly-five-tons-of-lead-azide-in-iowa-town"]'::jsonb, 'A review can help, but the Army did consult multiple agencies. A new review would be useful only if the hazard allowed time for it.'),
  ('iowa-army-detonation', '86ef5988-a8ce-50b5-81c5-a044e2a163c7', 'Require stronger review', 13, 'Give communities earlier notice', 'The timeline changed repeatedly, and AP reported frustration about lack of information. Earlier outreach through local institutions could have given families, schools and employers more time to arrange transportation, childcare and time off.', '["https://www.army.mil/article/297039/public_safety_advisory_controlled_mitigated_detonation_of_unstable_lead_azide_at_iowa_army_ammunition_plant", "https://apnews.com/article/iowa-lead-detonation-714e040baedc1cd90c2ba688be76cfc7", "https://earthjustice.org/press/2026/army-detonates-nearly-five-tons-of-lead-azide-in-iowa-town"]'::jsonb, 'The final public advisory offered practical help and the agencies adjusted plans as conditions changed. Some short-notice choices are unavoidable in an emergency.'),
  ('iowa-army-detonation', 'ba85e709-704f-587e-843a-5e7d3fa5340c', 'Require stronger review', 15, 'Explain what delay improved', 'Court filings say the later date allowed additional protections. The challengers credit legal action and community pressure for changes. Whether or not litigation caused each change, the initial plan deserved scrutiny because the later operation differed.', '["https://earthjustice.org/wp-content/uploads/2026/11/2026-11-23-doj-notice-of-operation.pdf", "https://earthjustice.org/press/2026/army-detonates-nearly-five-tons-of-lead-azide-in-iowa-town", "https://apnews.com/article/iowa-lead-detonation-714e040baedc1cd90c2ba688be76cfc7"]'::jsonb, 'A better plan after a short delay does not establish that each further delay would have made the community safer.'),
  ('iowa-army-detonation', '23fa584e-64a7-5564-ae28-5bee5c2e45fa', 'Require stronger review', 2, 'Test what may have settled', 'The EPA’s early statement was about real-time air monitoring. Scientists quoted by AP said lab analysis would still be necessary. Land, water, and surface dust are separate questions, especially for places in or near the suspected path.', '["https://www.epa.gov/newsreleases/initial-air-monitoring-shows-zero-detection-airborne-lead-following-controlled", "https://apnews.com/article/iowa-lead-detonation-714e040baedc1cd90c2ba688be76cfc7", "https://www.epa.gov/newsreleases/epa-collects-over-1200-air-land-and-water-samples-ahead-iowa-army-ammunition-plant"]'::jsonb, 'The absence of a complete lab record that day is expected. It is a reason to track follow-up, not proof of contamination.'),
  ('iowa-army-detonation', '365e950b-4907-5d17-9303-3d1019d1094e', 'Require stronger review', 8, 'Map gaps in the testing', 'Residents need to know where EPA tested, the limits of detection, and which properties or pathways were outside the monitoring network. A summary of online monitor readings is easier to interpret when that information is public.', '["https://www.epa.gov/newsreleases/epa-collects-over-1200-air-land-and-water-samples-ahead-iowa-army-ammunition-plant", "https://www.epa.gov/newsreleases/initial-air-monitoring-shows-zero-detection-airborne-lead-following-controlled", "https://epa.illinois.gov/about-us/illinois-epa-news/illinois-remains-on-standby-following-lead-azide-detonation-at-t.html"]'::jsonb, 'Agencies collected many baseline samples and provided live monitoring. The next step is to make those existing data and limitations understandable.'),
  ('iowa-army-detonation', 'd4d4c8b3-3142-5a6f-868a-444fc5cb56b3', 'Require stronger review', 17, 'Plan for uneven disruption', 'AP reported that schools and businesses closed and some residents were advised to leave or stay indoors. A plan deserves scrutiny over who could follow it, which wages or appointments were lost, and how assistance reached people.', '["https://apnews.com/article/iowa-lead-detonation-714e040baedc1cd90c2ba688be76cfc7", "https://www.army.mil/article/297039/public_safety_advisory_controlled_mitigated_detonation_of_unstable_lead_azide_at_iowa_army_ammunition_plant", "https://earthjustice.org/press/2026/army-detonates-nearly-five-tons-of-lead-azide-in-iowa-town"]'::jsonb, 'Any serious incident could disrupt daily life. A planned event at least gives officials a chance to reduce disruption and offer help.'),
  ('iowa-army-detonation', 'e3176d74-73e9-5254-9f0a-dcc48dcf8299', 'Require stronger review', 19, 'Keep state oversight through cleanup', 'Illinois reported little to no expected impact but stayed on standby pending final federal data. The same cross-border information sharing matters after the operation as before it, so residents know which agency owns follow-up.', '["https://epa.illinois.gov/about-us/illinois-epa-news/illinois-remains-on-standby-following-lead-azide-detonation-at-t.html", "https://apnews.com/article/iowa-lead-detonation-714e040baedc1cd90c2ba688be76cfc7"]'::jsonb, 'Illinois’s decision to monitor prudently is compatible with concluding that the federal operation was the right immediate choice.'),
  ('iowa-army-detonation', '967d98ef-9764-5535-93c7-1aa99e173e6c', 'Require stronger review', 4, 'Demand a public after-action review', 'Publish the storage timeline, how leaders weighed alternatives, and who pays for follow-up if lab work identifies contamination. The community should be able to judge the next emergency by the lessons from this one.', '["https://earthjustice.org/press/2026/army-detonates-nearly-five-tons-of-lead-azide-in-iowa-town", "https://www.epa.gov/newsreleases/initial-air-monitoring-shows-zero-detection-airborne-lead-following-controlled", "https://epa.illinois.gov/about-us/illinois-epa-news/illinois-remains-on-standby-following-lead-azide-detonation-at-t.html"]'::jsonb, 'An after-action review is worthwhile regardless of which side was right on November 25. It should preserve the evidence behind the emergency decision.')
insert into dk_editorial.discussion_comments(id,slug,excerpt) values
  ('3da98a2a-0777-5388-9c42-d8eb8041b7cb', 'iowa-army-detonation', 'I’d have gone ahead on Wednesday. At the help desk, waiting for the perfect diagnosis sometimes leaves everybody without a backup. Here the Army said the hazard could go off without warning and moving it was too risky. The better weather and people on the ground made the planned option easier for me to defend.'),
  ('2d5bf75f-ff93-5ca1-beb2-d5c5f8ce48b0', 'iowa-army-detonation', 'I’m glad the early monitors didn’t pick up lead. My question is why the case for a deadline was so hard to inspect until the last minute. If a short review and clearer instructions could have cut the risk, I’d have wanted them before signing off. I don’t think a no-detection reading settles what might have landed on a farm.'),
  ('ffc557ff-8142-588b-90fa-b9a2a69fe871', 'iowa-army-detonation', 'Fair. An air monitor can’t tell you everything that happened at ground level. Compare the soils and surfaces to the EPA baseline, publish the map and limits, and say who handles cleanup. I can defend the response on Wednesday and still want answers about the years before it.'),
  ('ef68e520-17f5-518c-9f62-260fd44f2078', 'iowa-army-detonation', 'We’re close on the cleanup. If an independent review shows those extra hours really raised the chance of a surprise explosion, I’ll give the Army more credit for the timing. I’d also like the residents who had to leave to tell us whether the support actually worked.')
